use axum::response::Html;

pub async fn page() -> Html<String> {
    crate::ui::render(
        "Gérer une application",
        "/developer",
        r####"<div class="page-heading"><div class="eyebrow"><a href="/developer">Applications</a> / Configuration</div><h1 id="client-title">Configuration de l'application</h1><p class="lead">Gérez les adresses de retour, le secret web et l'activation de cette intégration.</p></div><div class="columns"><section class="panel"><input id="client_id" type="hidden"><div class="toolbar"><span class="hint">Identifiant : <code id="client-id-display" class="mono">—</code></span><button class="secondary" type="button" id="load">Actualiser</button></div><div id="client-content" hidden><h2>Adresses de retour</h2><p class="muted">Autorisez uniquement les adresses exactes utilisées par votre application.</p><label>URI autorisées<textarea id="redirects" spellcheck="false"></textarea></label><button type="button" id="save" style="margin-top:14px">Enregistrer les adresses</button><section id="web-secret" hidden><hr><h2>Secret du client web</h2><p class="muted">Un nouveau secret invalide l'ancien. Conservez-le uniquement dans le backend de votre application. Il ne sera affiché qu'une fois.</p><label>Confirmer avec votre clé administrateur<input type="password" id="admin_token" autocomplete="off"></label><button type="button" class="secondary" id="rotate" style="margin-top:14px">Générer un nouveau secret</button><div class="notice" id="secret-result" hidden><strong>Copiez et sauvegardez ce secret maintenant. Il ne sera plus affiché.</strong><p class="mono" id="secret"></p><button type="button" class="secondary" id="copy-secret">Copier</button></div></section><section id="disable-section"><hr><h2>Désactiver l'application</h2><p class="muted">Cette opération bloque les futures connexions et l'utilisation des jetons de cette application.</p><label><input type="checkbox" id="confirm_disable"> Je confirme vouloir désactiver cette application.</label><button type="button" class="danger" id="disable" style="margin-top:14px">Désactiver l'application</button></section></div><p class="status" id="status" role="status" aria-live="polite"></p></section><aside class="panel"><h2>Points à vérifier</h2><p class="muted">Chaque adresse de retour doit correspondre exactement à celle utilisée par votre application.</p><p class="muted">Changer le secret web invalide immédiatement le précédent.</p><p class="muted">La désactivation bloque les futurs échanges de jetons et n'est pas réversible depuis cette interface.</p><a href="/developer">Retour aux applications</a></aside></div><script>
const id=document.getElementById('client_id'),status=document.getElementById('status'),content=document.getElementById('client-content');id.value=new URLSearchParams(location.search).get('client_id')||'';
const endpoint=s=>'/developer/clients/'+encodeURIComponent(id.value.trim())+s;
function notify(message,error=false){status.textContent=message;status.dataset.error=String(error);}
async function load(){try{const r=await fetch('/developer/clients',{credentials:'same-origin'});if(!r.ok){notify('Connectez-vous à la console développeur.',true);return;}const app=(await r.json()).find(v=>v.client_id===id.value.trim());if(!app){notify('Application introuvable.',true);return;}content.hidden=false;document.getElementById('client-title').textContent=app.name;document.title=app.name+' · Donnarieix Auth';document.getElementById('client-id-display').textContent=app.client_id;document.getElementById('web-secret').hidden=app.client_type!=='web'||!app.active;document.getElementById('disable-section').hidden=!app.active;document.getElementById('redirects').value=(app.redirect_uris||[]).join('\n');document.getElementById('rotate').disabled=app.client_type!=='web'||!app.active;document.getElementById('save').disabled=!app.active;document.getElementById('disable').disabled=!app.active;notify(app.name+' · '+(app.active?'Active':'Désactivée'));}catch{notify('Impossible de charger les données.',true);}}
document.getElementById('load').addEventListener('click',load);
document.getElementById('save').addEventListener('click',async()=>{const uris=document.getElementById('redirects').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const r=await fetch(endpoint('/redirects'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({redirect_uris:uris})});notify(r.ok?'Adresses enregistrées.':'Modification refusée.',!r.ok);});
document.getElementById('rotate').addEventListener('click',async()=>{const field=document.getElementById('admin_token'),administrator_token=field.value;field.value='';document.getElementById('secret').textContent='';document.getElementById('secret-result').hidden=true;const r=await fetch(endpoint('/secret'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({administrator_token})});if(!r.ok){notify('Clé refusée ou client web indisponible.',true);return;}document.getElementById('secret').textContent=(await r.json()).client_secret;document.getElementById('secret-result').hidden=false;notify('Nouveau secret généré.');});
document.getElementById('copy-secret').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('secret').textContent);notify('Secret copié.');}catch{notify('Copie impossible, sélectionnez le texte.',true);}});
document.getElementById('disable').addEventListener('click',async()=>{if(!document.getElementById('confirm_disable').checked){notify('Confirmez la désactivation.',true);return;}if(!confirm('Désactiver définitivement cette application ?'))return;const r=await fetch(endpoint('/disable'),{method:'POST',credentials:'same-origin'});notify(r.ok?'Application désactivée.':'Désactivation refusée.',!r.ok);if(r.ok)load();});
if(id.value){load();}else{document.getElementById('load').hidden=true;notify('Choisissez d’abord une application dans la liste.',true);}
</script>"####,
    )
}
